function portfolioCards(lang){
  const ui=PORTFOLIO_UI[lang];
  return PORTFOLIO_PROJECTS.map((p,i)=>{
    const d=p[lang],featured=i===4;
    return `<article class="portfolio-card ${featured?'portfolio-card--featured':''}">
      <button type="button" class="portfolio-art portfolio-art--${p.id}" data-project="${p.id}" aria-label="${esc(ui.view+': '+d.name)}">
        <img src="${A[p.image]}" alt="${esc(d.alt)}" loading="${i<2?'eager':'lazy'}" decoding="async">
      </button>
      <div class="portfolio-description"><div>
        ${featured?`<p class="portfolio-tagline">05 / SELECTED WORK</p>`:''}
        <p class="portfolio-meta">${String(i+1).padStart(2,'0')} / ${esc(d.sector)}</p>
        <h3>${esc(d.name)}</h3>
        <p class="portfolio-summary">${esc(d.summary)}</p>
      </div><button type="button" class="portfolio-detail-button" data-project="${p.id}" aria-label="${esc(ui.view+': '+d.name)}">${esc(ui.view)} ${arrow()}</button></div>
    </article>`;
  }).join('');
}
function portfolioSection(lang){
  const t=C[lang],ui=PORTFOLIO_UI[lang];
  return `<section id="work" class="section portfolio-section"><div class="container">
    <div class="section-heading"><div><p class="eyebrow"><span>01</span> ${esc(t.workLabel)}</p><h2>${nl(t.workTitle)}</h2></div><p class="section-intro portfolio-intro">${esc(ui.intro)}</p></div>
    <div class="portfolio-grid">${portfolioCards(lang)}</div><p class="portfolio-trust">${esc(t.portfolioTrust)}</p>
  </div></section>`;
}
function showPortfolioProject(id){
  const p=PORTFOLIO_PROJECTS.find(item=>item.id===id);if(!p)return;
  const d=p[currentLang],ui=PORTFOLIO_UI[currentLang];
  const modal=document.getElementById('projectDialog');
  if(!modal)return;
  document.getElementById('projectDialogContent').innerHTML=`
   <div class="portfolio-modal-hero portfolio-art--${p.id}"><img src="${A[p.image]}" alt="${esc(d.alt)}"></div>
   <div class="portfolio-modal-content">
     <p class="portfolio-modal-eyebrow"><span>${esc(d.sector)}</span></p>
     <h2 id="projectDialogTitle">${esc(d.name)}</h2>
     <p class="portfolio-modal-lead">${esc(d.headline)}</p>
     <p class="portfolio-modal-desc">${esc(d.detail)}</p>
     <div class="case-study-grid"><div class="case-study-block"><span class="case-study-index">01 / ${esc(ui.challenge)}</span><p>${esc(d.challenge)}</p></div><div class="case-study-block"><span class="case-study-index">02 / ${esc(ui.approach)}</span><p>${esc(d.approach)}</p></div></div>
     ${p.gallery?.length?`<div class="case-study-gallery"><p class="case-study-index">${esc(ui.gallery)}</p><div class="case-study-images">${p.gallery.map((key,i)=>`<img loading="lazy" src="${A[key]}" alt="${esc(C[currentLang].imageAlt[i]||d.alt)}">`).join('')}</div></div>`:''}
     <div class="portfolio-modal-grid"><div><h3>${esc(ui.services)}</h3><div class="portfolio-service-tags">${p.services.map(x=>`<span class="portfolio-service-tag">${esc(x)}</span>`).join('')}</div></div>
     <div><h3>${esc(ui.scope)}</h3><ul class="portfolio-work-list">${d.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>
     <p class="case-no-metrics">${esc(ui.resultNote)}</p>
     ${p.links.length?`<div class="portfolio-links">${p.links.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`).join('')}</div>`:''}
   </div>`;
  const close=modal.querySelector('.portfolio-dialog-close');close.setAttribute('aria-label',ui.close);
  modal.showModal();close.focus({preventScroll:true});
}

